import React from "react";

export default function Courses() {

const courses = [

{

id:1,

name:"Java Full Stack",

instructor:"Ramesh",

duration:"6 Months",

status:"Active"

},

{

id:2,

name:"Python Programming",

instructor:"Suresh",

duration:"4 Months",

status:"Completed"

},

{

id:3,

name:"React JS",

instructor:"Anitha",

duration:"3 Months",

status:"Active"

},

{

id:4,

name:"Database Management",

instructor:"Kiran",

duration:"2 Months",

status:"Upcoming"

}

];

return(

<div style={{

minHeight:"100vh",

background:"#f1f5f9",

padding:"40px"

}}>

<h1 style={{

textAlign:"center",

color:"#2563eb",

marginBottom:"40px"

}}>

📚 Courses

</h1>

<div style={{

display:"grid",

gridTemplateColumns:

"repeat(auto-fit,minmax(280px,1fr))",

gap:"25px"

}}>

{

courses.map((course)=>(

<div

key={course.id}

style={{

background:"white",

padding:"25px",

borderRadius:"20px",

boxShadow:

"0 8px 20px rgba(0,0,0,0.1)"

}}

>

<h2 style={{

color:"#1e293b"

}}>

{course.name}

</h2>

<p>

<b>Instructor :</b>

{course.instructor}

</p>

<p>

<b>Duration :</b>

{course.duration}

</p>

<p>

<b>Status :</b>

<span

style={{

color:

course.status==="Active"

?

"green"

:

course.status==="Completed"

?

"blue"

:

"orange",

fontWeight:"bold"

}}

>

{course.status}

</span>

</p>

<button

style={{

marginTop:"15px",

width:"100%",

padding:"12px",

background:"#2563eb",

color:"white",

border:"none",

borderRadius:"10px",

cursor:"pointer"

}}

onClick={()=>

alert(

"You Enrolled in "

+

course.name

)

}

>

Enroll Course

</button>

</div>

))

}

</div>

</div>

)

}
